import type { CSSProperties } from "react";

/* ------------------------------------------------------------------ */
/* Port dot — geometry re-measured against the real SystemSketch app   */
/* (see the donor file's own header for provenance).                   */
/* ------------------------------------------------------------------ */

export const PORT_DIAMETERS = { sm: 8, md: 12, lg: 18 } as const;
export type PortSize = keyof typeof PORT_DIAMETERS | number; // number = "Exact"

export const PORT_DIAMETER_LABELS: Record<keyof typeof PORT_DIAMETERS, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
};

export const PORT_SURFACE_RING_PX = 2;
export const PORT_STATE_RING_PX = 3;
// WHY: the rings are box-shadow, painted OUTSIDE the dot's layout box — any
// spacing measured from the box edge must add this or the ring eats it.
export const PORT_RING_OVERHANG_PX = PORT_SURFACE_RING_PX + PORT_STATE_RING_PX;
export const PORT_HIT_PX = 40;

/**
 * The six legacy named label placements, widened back from four in the
 * donor's own 2026-09-12 change — "Right Offset"/"Left Offset" lift the
 * label clear of a trace wire (see `TEXT_LAYOUT_AS_PLACEMENT` below).
 */
export type PortTextLayout = "top" | "bot" | "right" | "left" | "rightOffset" | "leftOffset";

export const PORT_TEXT_LAYOUTS: PortTextLayout[] = [
  "top",
  "bot",
  "right",
  "left",
  "rightOffset",
  "leftOffset",
];

export const PORT_TEXT_LAYOUT_LABELS: Record<PortTextLayout, string> = {
  top: "Top",
  bot: "Bot",
  right: "Right",
  left: "Left",
  rightOffset: "Right Offset",
  leftOffset: "Left Offset",
};

export const PORT_LABEL_GAP = 8;

/**
 * The flex row's direction for a resolved ORIGIN — so the Expert
 * `labelOrigin` control (or a host's own `edge`/`textLayout` choice) always
 * matches which side the row actually lays the label on.
 */
export function originFlexDirection(
  origin: SlotOrigin,
): "row" | "row-reverse" | "column" | "column-reverse" {
  switch (origin) {
    case "top":
      return "column-reverse"; // label above the dot
    case "bottom":
      return "column";
    case "right":
      return "row";
    case "left":
      return "row-reverse";
  }
}

/** True for the two legacy label positions that lift the label clear of a
 *  trace wire — derived from `TEXT_LAYOUT_AS_PLACEMENT`, not a second
 *  hand-written list. */
export function isOffsetTextLayout(layout: PortTextLayout): boolean {
  return TEXT_LAYOUT_AS_PLACEMENT[layout].align === "end";
}

export type PortDirection = "input" | "output";
export const PORT_DIRECTIONS: PortDirection[] = ["input", "output"];
export const PORT_DIRECTION_LABELS: Record<PortDirection, string> = {
  input: "Input",
  output: "Output",
};

export type BlockSide = "left" | "right" | "top" | "bottom";
export const BLOCK_SIDES: BlockSide[] = ["left", "right", "top", "bottom"];
export const BLOCK_SIDE_LABELS: Record<BlockSide, string> = {
  left: "Left",
  right: "Right",
  top: "Top",
  bottom: "Bottom",
};

const SIDE_FOR_DIRECTION: Record<PortDirection, BlockSide> = {
  input: "left",
  output: "right",
};

export function portSideForDirection(direction: PortDirection): BlockSide {
  return SIDE_FOR_DIRECTION[direction];
}

/** Which way the label flows from the dot by default: inward, into the
 * block's interior, away from whatever the port connects to outside. */
export function inwardTextLayout(side: BlockSide): PortTextLayout {
  switch (side) {
    case "left":
      return "right";
    case "right":
      return "left";
    case "top":
      return "bot";
    case "bottom":
      return "top";
  }
}

/** Port's own text-size rung — same four px values as EditableText's
 * ladder (`editableText.layout.ts`'s `EDITABLE_TEXT_SIZES`), so a
 * `PortTextSize` passes straight through as an `EditableTextSize` with no
 * translation table. */
export const PORT_TEXT_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
export type PortTextSize = keyof typeof PORT_TEXT_SIZES;
export const PORT_TEXT_SIZE_LABELS: Record<PortTextSize, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
  xl: "Extra Large",
};

/**
 * `PortDot`'s second independently-positioned slot: generic content hugging
 * a corner of the dot, closer in than the label slot's own "Offset"
 * positions.
 */
export type SecondarySlotLayout = "leftOffset" | "rightOffset" | "topOffset" | "botOffset";

export const SECONDARY_SLOT_LAYOUTS: SecondarySlotLayout[] = [
  "leftOffset",
  "rightOffset",
  "topOffset",
  "botOffset",
];

export const SECONDARY_SLOT_LAYOUT_LABELS: Record<SecondarySlotLayout, string> = {
  leftOffset: "Left Offset",
  rightOffset: "Right Offset",
  topOffset: "Top Offset",
  botOffset: "Bot Offset",
};

/** How tightly the secondary slot hugs the dot's own box — deliberately
 * smaller than `PORT_LABEL_GAP` (a badge/cue hugging a corner, not content
 * sitting flush beside the dot). */
export const PORT_SECONDARY_SLOT_GAP_PX = 6;

/** The secondary slot's AUTO default position — the corner opposite
 * wherever the label is actually flowing. Only consulted when a caller
 * omits `secondarySlotLayout` outright; an explicit value always wins. */
export function defaultSecondarySlotLayout(labelLayout: PortTextLayout): SecondarySlotLayout {
  switch (labelLayout) {
    case "left":
    case "leftOffset":
      return "rightOffset";
    case "right":
    case "rightOffset":
      return "leftOffset";
    case "top":
      return "botOffset";
    case "bot":
      return "topOffset";
  }
}

/* ------------------------------------------------------------------ */
/* THE UNIFIED SLOT PLACEMENT MODEL                                    */
/* ------------------------------------------------------------------ */

/** Which side of the dot a slot anchors to — the ORIGIN. Shared by both
 * slots; the named `PortTextLayout`/`SecondarySlotLayout` members are
 * PRESETS over (origin, offsetX, offsetY), not a parallel vocabulary. */
export type SlotOrigin = "top" | "bottom" | "left" | "right";

export const SLOT_ORIGINS: SlotOrigin[] = ["top", "bottom", "left", "right"];

export const SLOT_ORIGIN_LABELS: Record<SlotOrigin, string> = {
  top: "Top",
  bottom: "Bottom",
  left: "Left",
  right: "Right",
};

/**
 * WHICH PART OF THE SLOT is the reference point, on the axis the origin
 * leaves free — "end" is what makes "clear of the trace wire" a static
 * offset instead of one derived from the label's own (unknowable) height:
 * `translate(…, -100%)` puts the chosen edge ON the reference line whatever
 * the slot's content measures.
 */
export type SlotAlign = "start" | "center" | "end";

export const SLOT_ALIGNS: SlotAlign[] = ["start", "center", "end"];

const ALIGN_SHIFT: Record<SlotAlign, string> = {
  start: "0%",
  center: "-50%",
  end: "-100%",
};

export interface SlotPlacement {
  origin: SlotOrigin;
  align: SlotAlign;
  offsetX: number;
  offsetY: number;
}

/** A port dot's box, named so it cannot be mistaken for anything else. */
export interface PortDotBox {
  w: number;
  h: number;
}

/**
 * CSS offsets for a slot absolutely positioned against the dot's box. Plain
 * data — spreads into any host's `style` object.
 */
export interface PortLabelPlacement extends CSSProperties {
  left?: string;
  right?: string;
  top?: string;
  bottom?: string;
  transform: string;
}

/**
 * THE ONE ANCHOR RULE: the slot's content anchors by the edge FACING its
 * origin, centred on the other axis, sitting `gap` clear of the dot's
 * PAINTED ring; `offsetX`/`offsetY` then translate it from there in SCREEN
 * space (so `+x` always means "rightward on screen", on every origin).
 */
export function slotPlacementStyle(
  placement: SlotPlacement,
  dot: PortDotBox,
  gapPx: number,
  boxInsetPx: number = 0,
): PortLabelPlacement {
  const { origin, align, offsetX, offsetY } = placement;
  const shift = ALIGN_SHIFT[align];
  const outX = `${dot.w + PORT_RING_OVERHANG_PX + gapPx - boxInsetPx}px`;
  const outY = `${dot.h + PORT_RING_OVERHANG_PX + gapPx - boxInsetPx}px`;
  switch (origin) {
    case "right":
      return { left: outX, top: "50%", transform: `translate(${offsetX}px, calc(${shift} + ${offsetY}px))` };
    case "left":
      return { right: outX, top: "50%", transform: `translate(${offsetX}px, calc(${shift} + ${offsetY}px))` };
    case "top":
      return { bottom: outY, left: "50%", transform: `translate(calc(${shift} + ${offsetX}px), ${offsetY}px)` };
    case "bottom":
      return { top: outY, left: "50%", transform: `translate(calc(${shift} + ${offsetX}px), ${offsetY}px)` };
  }
}

/**
 * The six-member `PortTextLayout` as (origin, align, offsetY) — the two
 * "Offset" members are a STATIC placement: anchor the slot's bottom edge
 * (`align: "end"`) on the dot's centre line, then push it up one gap.
 * Height-independent by construction — no lift computed from the label's
 * own (unknowable) height. `portLabelLift()` no longer exists; this table
 * is its replacement (see docs/PORT-EDGE-PLAN.md's own note on this).
 */
export const TEXT_LAYOUT_AS_PLACEMENT: Record<
  PortTextLayout,
  { origin: SlotOrigin; align: SlotAlign; offsetY: number }
> = {
  top: { origin: "top", align: "center", offsetY: 0 },
  bot: { origin: "bottom", align: "center", offsetY: 0 },
  right: { origin: "right", align: "center", offsetY: 0 },
  left: { origin: "left", align: "center", offsetY: 0 },
  rightOffset: { origin: "right", align: "end", offsetY: -PORT_LABEL_GAP },
  leftOffset: { origin: "left", align: "end", offsetY: -PORT_LABEL_GAP },
};

/** The same compatibility read for the secondary slot's own four-member
 *  enum — every member is a corner hug, so none is "lifted". */
export const SECONDARY_LAYOUT_AS_ORIGIN: Record<SecondarySlotLayout, SlotOrigin> = {
  leftOffset: "left",
  rightOffset: "right",
  topOffset: "top",
  botOffset: "bottom",
};

"use client";

// src/components/port.tsx — ported by value from packages/bbox-ui/src/port.tsx
// (docs/PORT-EDGE-PLAN.md Phase 1). `Port` is the geometry alone: the disc,
// the 2px surface ring, the 3px state ring, the lit core, the 40px hit halo.
// It knows nothing about labels or slots — `./labeledPort.tsx` is the
// composite that adds those.
//
// What ported OVER verbatim (pure geometry/paint, no schema): `portDotClass`,
// the ring/halo/core layering.
//
// What's LEFT BEHIND (docs/PORT-EDGE-PLAN.md's own list — none of it is
// geometry): `resolveField`/`PORT_PRESETS`/the `size` cascade rung (D4 —
// `diameter` is a direct prop here), `tone`/`lens`/`reveal`/`producers` (D3 —
// the sketch's six states don't need them, each is re-addable later), and
// `anchored` (wall geometry for a real Block).

import type { ComponentProps, CSSProperties } from "react";

import { cn } from "../lib/utils";
import { PORT_DIAMETERS, PORT_HIT_PX, PORT_STATE_RING_PX, PORT_SURFACE_RING_PX, type PortSize } from "./port.layout";

/* ------------------------------------------------------------------ */
/* Colour — state -> token, inlined from packages/bbox-ui's appearance.ts */
/* (STATE_TOKENS/paintVar), tone channel removed (D3) so there is no      */
/* color-mix blend step: a token resolves straight to `var(--token)`.     */
/* ------------------------------------------------------------------ */

/**
 * The board's four-value axis — "what is in the port": empty, a default
 * value set, wired to something, or data has flowed through it just now.
 * `dimmed`/`hidden` are NOT rungs of this union (see `PortProps`'s own
 * docs) — neither is a fact about what the port IS.
 */
export type PortState = "empty" | "valueSet" | "wired" | "received";

export const PORT_STATES: PortState[] = ["empty", "valueSet", "wired", "received"];

export const PORT_STATE_LABELS: Record<PortState, string> = {
  empty: "Empty",
  valueSet: "Default Value",
  wired: "Wired",
  received: "Data Received",
};

interface StateTokenPair {
  ring: string | null;
  fill: string | null;
  core: string | null;
}

const STATE_TOKENS: Record<PortState, StateTokenPair> = {
  empty: { ring: "foreground", fill: null, core: null },
  valueSet: { ring: "muted-foreground", fill: "muted", core: null },
  wired: { ring: "primary", fill: null, core: "primary" },
  received: { ring: "bbox-received", fill: "bbox-received", core: "bbox-received" },
};

/**
 * `primary` resolves through the bbox accent (with a fallback to whatever
 * host `--primary` already means) so "wired" reads as the design system's
 * own orange rather than the host's button colour — same special case
 * `paintVar` makes in the donor package. `--bbox-primary`/`--bbox-received`
 * are the two tokens this phase appends to `src/globals.css`.
 */
export function paintVar(token: string): string {
  return token === "primary" ? "var(--bbox-primary, var(--primary))" : `var(--${token})`;
}

/* ------------------------------------------------------------------ */
/* The dot's paint                                                     */
/* ------------------------------------------------------------------ */

export interface PortDotPaintInput {
  state?: PortState;
  dimmed?: boolean;
  hinting?: boolean;
}

/**
 * Static half of the dot's class — sizing/shape/transition only. Every
 * colour fact is dynamic per state and lives in `portDotStyle` instead.
 *
 * `hover:scale-110` is a real CSS `:hover` pseudo-class, deliberately NOT a
 * `hover` prop — nothing outside this component ever needs to SET hover.
 */
export function portDotClass(): string {
  return "relative box-border inline-flex shrink-0 rounded-full transition-transform duration-[50ms] ease-in-out hover:scale-110 motion-reduce:transition-none motion-reduce:hover:scale-100";
}

/**
 * The dot's ring/fill. `dimmed` forces the ring to `muted-foreground` and
 * fades the whole dot to ~45% opacity, leaving the resting fill/core colour
 * underneath untouched (a dimmed `wired` port still reads "wired, just not
 * focused right now"). `hinting` wears `wired`'s own shape (hollow ring, lit
 * core) in the accent colour regardless of `state` — previewing the port
 * BECOMING wired, with a wide halo.
 */
export function portDotStyle({ state = "empty", dimmed = false, hinting = false }: PortDotPaintInput): CSSProperties {
  const { ring, fill } = STATE_TOKENS[state];
  const ringColor = hinting ? paintVar("primary") : dimmed ? paintVar("muted-foreground") : ring ? paintVar(ring) : null;
  // `hinting` renders hollow (no fill), matching `wired`'s own shape.
  const fillColor = hinting ? null : fill ? paintVar(fill) : null;

  const layers: string[] = [];
  if (ringColor != null) {
    const stateRingPx = hinting ? 4 : PORT_STATE_RING_PX;
    layers.push(`0 0 0 ${PORT_SURFACE_RING_PX}px var(--card)`);
    layers.push(`0 0 0 ${PORT_SURFACE_RING_PX + stateRingPx}px ${ringColor}`);
  }
  if (hinting) {
    layers.push("0 0 0 9px color-mix(in srgb, var(--bbox-primary, var(--primary)) 38%, transparent)");
  }

  const style: CSSProperties = {};
  if (layers.length > 0) style.boxShadow = layers.join(", ");
  // Opaque resting paint, never transparent — a wall-mounted dot straddles a
  // block's border, and a transparent interior would let it show through a
  // hollow (`empty`/`wired`) dot. `var(--card)` is the same token the 2px
  // surface ring already uses, so ring and disc read as one punch-out.
  style.background = fillColor ?? "var(--card)";
  if (dimmed && !hinting) style.opacity = 0.45;
  if (hinting) style.transform = "scale(1.18)";
  return style;
}

/** The core's own diameter as a fraction of the dot's. */
const PORT_CORE_RATIO = 0.42;

/**
 * The small inner "core" dot: lit for `wired` (disc stays hollow, core lit
 * instead of a solid fill) and `received` (core matches the already-solid
 * fill, reading as "fully lit"). `null` means no core layer at all, not a
 * transparent one — `empty`/`valueSet` never mount the extra span.
 */
export function portCoreStyle({ state = "empty", hinting = false }: PortDotPaintInput): CSSProperties | null {
  const core = hinting ? "primary" : STATE_TOKENS[state].core;
  if (core == null) return null;
  return { background: paintVar(core) };
}

/* ------------------------------------------------------------------ */
/* Port — the dot alone: the disc + both rings + the lit core + the    */
/* 40px hit halo. Knows nothing about labels or slots.                 */
/* ------------------------------------------------------------------ */

export interface PortProps extends ComponentProps<"span"> {
  state?: PortState;
  diameter?: PortSize;
  /** Author-set, persisted. Genuinely absent when true — `if (hidden)
   * return null`, no element, no 40px halo, no pointer events at all. Not
   * "opacity 0, still clickable" — Zach's own annotation on the sketch:
   * "Completely remove it, we don't want it to be selectable either." */
  hidden?: boolean;
  /** Host-set, never persisted — the port is out of focus, or mid-drag and
   * not a legal target. Composes OVER the resting paint (a dimmed `wired`
   * port stays legible as "wired, unfocused"), never a fifth `state`. */
  dimmed?: boolean;
  /** Host-set, never persisted — the pointer is over this port mid-drag,
   * previewing it becoming `wired`. */
  hinting?: boolean;
}

/**
 * The dot alone. `hidden` renders NOTHING — not a fifth visual state, a
 * visibility fact (see `PortProps.hidden`'s own doc, and Port.stories.tsx's
 * `Hidden` story, which asserts the DOM node is actually gone).
 */
export function Port({
  state = "empty",
  diameter = "md",
  hidden = false,
  dimmed = false,
  hinting = false,
  className,
  style,
  ...props
}: PortProps) {
  if (hidden) return null;
  const diameterPx = typeof diameter === "number" ? diameter : PORT_DIAMETERS[diameter];
  // A fixed 40px hit target regardless of the painted diameter.
  const haloInset = (diameterPx - PORT_HIT_PX) / 2;
  const coreStyle = portCoreStyle({ state, hinting });
  return (
    <span
      data-slot="port-dot"
      data-state={state}
      data-diameter={diameter}
      data-dimmed={dimmed || undefined}
      data-hinting={hinting || undefined}
      className={cn(portDotClass(), className)}
      style={{
        width: diameterPx,
        height: diameterPx,
        ...portDotStyle({ state, dimmed, hinting }),
        ...style,
      }}
      {...props}
    >
      <span data-slot="port-dot-halo" aria-hidden className="absolute rounded-full" style={{ inset: haloInset }} />
      {coreStyle && (
        <span
          data-slot="port-dot-core"
          aria-hidden
          className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full"
          style={{ width: `${PORT_CORE_RATIO * 100}%`, height: `${PORT_CORE_RATIO * 100}%`, ...coreStyle }}
        />
      )}
    </span>
  );
}

/**
 * src/components/portEdge.layout.ts — the pure data/math half of PortEdge,
 * ported by value from `demos/dndkit-lab/src/{types,layout,grouping}.ts`
 * and (Stage 6's new piece) `groupSyntax.ts` on the unmerged
 * `claude/dndkit-lab` branch, commit 5898ecb (docs/PORT-EDGE-PLAN.md's D2:
 * copy the lab's LOGIC as props, never merge the branch).
 *
 * Generalized in exactly one place versus the donor: `computeSlots`/
 * `buildColorMap` read the lab's fixed module-level `CARD_IDS` constant;
 * here they take the caller's own id list, since `PortEdge` has no fixed
 * card roster of its own. Everything else — `mainAxisPositions`,
 * `distributionStyle`, the grouping/clustering algorithm, the group-syntax
 * parser — is unchanged math.
 *
 * DONOR LINE NUMBERS, so a re-sync is a diff and not a search. All four
 * files read at commit 5898ecb on 2026-09-17 (`git show 5898ecb:<path>`;
 * the branch is unmerged but the commit is in this repo, so these resolve
 * offline forever):
 *
 *   • `layout.ts:39-69`   `mainAxisPositions` — byte-identical arithmetic.
 *   • `layout.ts:71-74`   `clamp`.
 *   • `grouping.ts:111-127` `computeSlots` — the one generalization above.
 *     The donor's line 121 reads `CARD_IDS.filter((cid) => ...)`; here that
 *     is `order.filter(...)`. Its third parameter is also widened, from the
 *     donor's `clustered: boolean` to this file's three-state `mode`.
 *   • `grouping.ts:129+`  `PALETTE`, and `buildColorMap` below it.
 *   • `groupSyntax.ts`    (72 lines) the whole group-syntax parser.
 *
 * PRIOR ART, for the one function here that implements a published spec
 * rather than a local convention — see `mainAxisPositions`' own docblock.
 * Everything else in this file is ad hoc: `computeSlots` is a stable
 * group-by preserving first-appearance order, and no prior art is claimed
 * for it.
 */
import type { CSSProperties } from "react";

/* ------------------------------------------------------------------ */
/* Spacing — demos/dndkit-lab/src/types.ts + layout.ts                 */
/* ------------------------------------------------------------------ */

export type SpacingScheme = "space-between" | "space-evenly" | "space-around";

export const SPACING_SCHEMES: { value: SpacingScheme; label: string; hint: string }[] = [
  {
    value: "space-between",
    label: "Edge to edge",
    hint: "space-between — first/last card flush against the container, gaps only between cards",
  },
  {
    value: "space-evenly",
    label: "Including edge",
    hint: "space-evenly — equal gap before the first card, between cards, and after the last",
  },
  {
    value: "space-around",
    label: "Around",
    hint: "space-around — equal margin on both sides of each card, so edge gaps end up half the between-card gap",
  },
];

export type AlignAnchor = "start" | "end";

export interface DistributeConfig {
  mode: "distribute";
  scheme: SpacingScheme;
}

export interface AlignConfig {
  mode: "aligned";
  anchor: AlignAnchor;
  /** px gap between cards. */
  gap: number;
  /** Extra px pushed in from the anchor edge, on top of the container's
   *  own padding — what makes one edge's ports start further along than
   *  another's. */
  edgePadding: number;
}

/** How a PortEdge lays its cards out along its main axis. `distribute` is
 *  the three space-* schemes (spreads across the whole container).
 *  `aligned` packs cards from one end with an explicit gap instead — the
 *  mode a real port edge needs, since "space-between" reflows every port's
 *  position the instant a sibling edge's count changes. */
export type Distribution = DistributeConfig | AlignConfig;

export const DEFAULT_ALIGN_GAP = 18;

/**
 * Lane E → Lane D (docs/FEEDBACK-2026-09-17c-PLAN.md, Lane E's own scoping
 * note): a `PortEdge` is one edge — it has no idea which of a Block's other
 * three edges carry ports, so it cannot decide its own default
 * `Distribution`. `BlockPort` is the one component that sees all four, so
 * this is the rule IT must apply; exported here (not duplicated as a
 * literal in blockPort.tsx) so both sides read the same source of truth:
 *
 *   • any populated edge is top or bottom → EVERY edge defaults to
 *     `{ mode: "distribute", scheme: "space-around" }` — `SPACING_SCHEMES`'
 *     own "Around" entry, Zach's "Distribute and Around" wording for it.
 *   • populated edges are left/right only → EVERY edge defaults to
 *     `{ mode: "aligned", anchor: "start" }` (the classic single-port-view
 *     packing: `DEFAULT_ALIGN_GAP`, no extra edge padding).
 *   • an explicit per-edge `distribution` from the caller always wins —
 *     this function only supplies what a caller omitted.
 *
 * `mainAxisPositions`'s own `space-around` branch already centres a lone
 * item with no `count === 1` special case beyond the one CSS itself
 * requires (see that function's own docblock) — verified, not
 * re-implemented, by `PortEdge.stories.tsx`'s `EdgeDistributionControls`.
 */
// Overloads so a caller passing a literal gets the NARROW arm back. Without
// them the return is the `Distribution` union, and `BlockPort` — which
// layers its own `gap`/`edgePadding` onto the aligned arm — cannot spread the
// result without TypeScript objecting that `gap` is absent from
// `DistributeConfig`. Narrowing here keeps the one-rule seam usable instead
// of pushing every caller back to a duplicated literal.
export function defaultDistributionForEdges(hasRowEdgePopulated: true): DistributeConfig;
export function defaultDistributionForEdges(hasRowEdgePopulated: false): AlignConfig;
export function defaultDistributionForEdges(hasRowEdgePopulated: boolean): Distribution;
export function defaultDistributionForEdges(hasRowEdgePopulated: boolean): Distribution {
  return hasRowEdgePopulated
    ? { mode: "distribute", scheme: "space-around" }
    : { mode: "aligned", anchor: "start", gap: DEFAULT_ALIGN_GAP, edgePadding: 0 };
}

export interface Size {
  width: number;
  height: number;
}

// Must match the inline padding/border PortEdge's own track applies below.
export const CONTAINER_PADDING = 14;
export const CONTAINER_BORDER = 2;

/** The box a free-positioned card is actually laid out in: the padding box. */
export function innerBoxSize(size: Size): Size {
  return { width: size.width - 2 * CONTAINER_BORDER, height: size.height - 2 * CONTAINER_BORDER };
}

/**
 * Reproduces CSS flexbox `justify-content` main-axis positions, so
 * switching into free-position ("Custom") mode can snapshot exactly where
 * the browser had already placed each card — no DOM measurement needed.
 */
/**
 * Where each card's leading edge sits along the main axis. Ported from
 * `demos/dndkit-lab/src/layout.ts:39-69` @ 5898ecb, arithmetic unchanged.
 *
 * PRIOR ART — this is not invented, it is CSS Box Alignment Level 3's
 * content-distribution, reimplemented in numbers because a host that places
 * ports on a canvas needs the POSITIONS, not a flex container. Spec read
 * 2026-09-17 at https://www.w3.org/TR/css-align-3/; each branch below
 * matches its normative definition, quoted:
 *
 *   space-between — "The first alignment subject is placed flush with the
 *     start edge of the alignment container, the last alignment subject is
 *     placed flush with the end edge" → first position 0, gap free/(n-1).
 *   space-evenly  — "with a full-size space on either end … the spacing
 *     between any two adjacent alignment subjects, before the first … and
 *     after the last … is the same" → gap free/(n+1), first at gap.
 *   space-around  — "with a half-size space on either end … the spacing
 *     before the first and after the last alignment subject is half the
 *     size of the other spacing" → gap free/n, first at gap/2.
 *
 * The `count === 1` branch is the one place the spec does not decide the
 * answer for us (there is no "between" with one subject); it reproduces
 * what browsers actually do, which is the donor's own stated reason at
 * `layout.ts:49-52` — "Matches browser behaviour". Not re-measured here.
 */
export function mainAxisPositions(count: number, mainSize: number, cardMain: number, scheme: SpacingScheme): number[] {
  if (count === 0) return [];
  const free = Math.max(mainSize - count * cardMain, 0);

  if (count === 1) {
    return scheme === "space-between" ? [0] : [free / 2];
  }

  switch (scheme) {
    case "space-between": {
      const gap = free / (count - 1);
      return Array.from({ length: count }, (_, i) => i * (cardMain + gap));
    }
    case "space-evenly": {
      const gap = free / (count + 1);
      return Array.from({ length: count }, (_, i) => gap + i * (cardMain + gap));
    }
    case "space-around": {
      const gap = free / count;
      return Array.from({ length: count }, (_, i) => gap / 2 + i * (cardMain + gap));
    }
  }
}

export function clamp(value: number, min: number, max: number): number {
  if (max < min) return min;
  return Math.min(Math.max(value, min), max);
}

/**
 * The main-axis CSS for a track given its Distribution. `distribute` reuses
 * the browser's own space-* keywords. `aligned` packs from one end with a
 * real `gap`, plus — when `edgePadding` is set — extra padding on that same
 * anchor side.
 */
export function distributionStyle(axis: "row" | "column", distribution: Distribution): CSSProperties {
  if (distribution.mode === "distribute") {
    return { justifyContent: distribution.scheme };
  }
  const style: CSSProperties = {
    justifyContent: distribution.anchor === "start" ? "flex-start" : "flex-end",
    gap: distribution.gap,
  };
  if (distribution.edgePadding > 0) {
    const prop =
      axis === "row"
        ? distribution.anchor === "start"
          ? "paddingLeft"
          : "paddingRight"
        : distribution.anchor === "start"
          ? "paddingTop"
          : "paddingBottom";
    (style as Record<string, number>)[prop] = CONTAINER_PADDING + distribution.edgePadding;
  }
  return style;
}

/**
 * Zach's rule for the "Offset" preset: the trailing edge's push-in clears
 * every leading slot AND the gap after it — `count * (slotMainPx + gap)`.
 *
 * FIXED 2026-09-17 (docs/PROPOSALS-2026-09-17.md P9a — the recorded IOU).
 * The original shipped as `count * gap`, which ignored the slots
 * themselves and under-shot by `count * slotMainPx` (72px for 3 empty
 * 24px slots at the default gap) — enough that the trailing lane's first
 * port lands INSIDE the leading lane's last slot instead of clear below
 * it, i.e. the two lanes visually interleave. `slotMainPx` has no default
 * here (unlike `blockPort.layout.ts`'s `offsetEdgePaddingPx`, which this
 * now matches formula-for-formula): this module is PortEdge's own generic
 * math and doesn't own a slot-size constant — `EMPTY_SLOT_MIN_PX` lives in
 * `portEdge.tsx`, `PORT_EDGE_SLOT_MIN_PX` in `blockPort.layout.ts` — so a
 * caller states its own slot size rather than this file guessing one.
 * Still an approximation in the one way the original docblock named and
 * this fix doesn't touch: a uniform `slotMainPx` assumes every leading
 * slot is the same size, which is only true with `showCard` off (a
 * variable-width card lane needs a caller-side sum over real slot rects,
 * not a closed form).
 *
 * `apps/storybook-basics/src/stories/OffsetPaddingFor.stories.tsx`'s
 * `OverlaidOffsetLanes` story is the regression: it renders two PortEdge
 * tracks sharing one coordinate frame with this formula as the trailing
 * track's `edgePadding`, and asserts — via real `getBoundingClientRect`
 * boxes — that no trailing slot's main-axis span overlaps a leading one's.
 * Restoring the old `count * gap` turns that story red (mutation-tested;
 * see the story file's own header for the transcript).
 */
export function offsetPaddingFor(count: number, slotMainPx: number, gap: number): number {
  return Math.max(0, count) * (slotMainPx + gap);
}

/* ------------------------------------------------------------------ */
/* Grouping — demos/dndkit-lab/src/grouping.ts, generalized off the     */
/* caller's own id list instead of a fixed CARD_IDS constant.           */
/* ------------------------------------------------------------------ */

export interface GroupAssignment {
  groupId: string;
  order: number;
}

export interface GroupingSetDef {
  id: string;
  label: string;
  description: string;
  /** Deliberately partial — an id missing here is not an error. Every id
   *  still resolves to SOME group: `resolveAssignment` falls back to the
   *  id's own value (a singleton group of one). */
  assignments: Record<string, GroupAssignment>;
}

export interface Slot {
  slotId: string;
  members: { id: string; order: number }[];
}

export function resolveAssignment(id: string, set: GroupingSetDef): GroupAssignment {
  return set.assignments[id] ?? { groupId: id, order: 0 };
}

/**
 * Walks the flat id order and clusters same-group ids into one slot each,
 * positioned wherever that group's first member currently sits — the
 * mechanism that makes "move together" and drag-as-one-unit the same thing:
 * whichever slot a drag relocates carries every member with it, in BOTH
 * `"grouped"` and `"collapsed"` mode (`"off"` never clusters). What differs
 * between the two is drawn by the caller, not by this function: `"grouped"`
 * still renders every member's own port (portEdge.tsx's `SlotBody` lays
 * them out along the edge's own axis, at the SAME pitch the rest of the
 * edge uses — B5/B7), `"collapsed"` renders the whole slot as one ×N chip
 * (unchanged — B8). Keeping the CLUSTERING itself unified here is what
 * keeps "grouped members drag as a unit" true for free: it's one
 * `useSortable` id either way, so dnd-kit's own live-reorder preview never
 * has to be taught about a multi-id unit.
 */
export function computeSlots(order: string[], set: GroupingSetDef, mode: "off" | "grouped" | "collapsed"): Slot[] {
  if (mode === "off") {
    return order.map((id) => ({ slotId: id, members: [{ id, order: 0 }] }));
  }
  const seen = new Set<string>();
  const slots: Slot[] = [];
  for (const id of order) {
    const { groupId } = resolveAssignment(id, set);
    if (seen.has(groupId)) continue;
    seen.add(groupId);
    const members = order
      .filter((cid) => resolveAssignment(cid, set).groupId === groupId)
      .map((cid) => ({ id: cid, order: resolveAssignment(cid, set).order }))
      .sort((a, b) => a.order - b.order);
    slots.push({ slotId: groupId, members });
  }
  return slots;
}

/**
 * The pixel gap BETWEEN adjacent top-level slot boxes a `Distribution`
 * actually produces on the edge's main axis — the same number flexbox
 * computes via CSS `gap` (`aligned`) or `justify-content` (`distribute`),
 * derived analytically (mirrors `mainAxisPositions`'s own per-scheme math)
 * rather than measured from the DOM.
 *
 * WHY a grouped (not collapsed) slot needs this at all (B5/B7): its members
 * render side by side INSIDE one slot, at their own internal `gap` — for
 * the whole edge's port-to-port pitch to stay uniform, that internal gap
 * must equal exactly this inter-slot gap, and every slot's own main-axis
 * box (`slotMainPx`) must be the same fixed size a single-port slot uses.
 * Given both of those, the "gap between box edges" flexbox guarantees is
 * uniform is the SAME gap on both sides of a group, so port-to-port
 * distance works out uniform everywhere: between two ungrouped ports,
 * between an ungrouped port and a group's near edge, and inside the group.
 */
export function interSlotGapPx(distribution: Distribution, containerMainPx: number, slotCount: number, slotMainPx: number): number {
  if (distribution.mode === "aligned") return distribution.gap;
  if (slotCount <= 1) return 0;
  const free = Math.max(containerMainPx - slotCount * slotMainPx, 0);
  switch (distribution.scheme) {
    case "space-between":
      return free / (slotCount - 1);
    case "space-evenly":
      return free / (slotCount + 1);
    case "space-around":
      return free / slotCount;
  }
}

export const PALETTE = [
  "#f59e0b", // amber
  "#22d3ee", // cyan
  "#a78bfa", // violet
  "#fb7185", // rose
  "#84cc16", // lime
  "#38bdf8", // sky
  "#fb923c", // orange
  "#e879f9", // fuchsia
];

/** One colour per real (>1 member) group, in first-appearance order —
 *  stable and legible, not hashed. */
export function buildColorMap(order: string[], set: GroupingSetDef): Map<string, string> {
  const sizes = new Map<string, number>();
  for (const id of order) {
    const { groupId } = resolveAssignment(id, set);
    sizes.set(groupId, (sizes.get(groupId) ?? 0) + 1);
  }
  const groupOrder: string[] = [];
  for (const id of order) {
    const { groupId } = resolveAssignment(id, set);
    if ((sizes.get(groupId) ?? 0) > 1 && !groupOrder.includes(groupId)) groupOrder.push(groupId);
  }
  const map = new Map<string, string>();
  groupOrder.forEach((groupId, i) => map.set(groupId, PALETTE[i % PALETTE.length]));
  return map;
}

/* ------------------------------------------------------------------ */
/* Group syntax — claude/dndkit-lab's groupSyntax.ts (5898ecb), net-new */
/* on that branch, ported unchanged (already generic over `knownIds`).  */
/* ------------------------------------------------------------------ */

/**
 * Zach, 2026-09-12: groups are something the EDGE assigns, not a value a
 * port carries. One textarea, one line per group, each a bracketed (or
 * bare) comma-separated list of ids: `[args,kwargs]`, `(args, kwargs)`,
 * and `args, kwargs` all parse identically. A line resolving to fewer than
 * 2 known members is dropped silently (a group of one is just an
 * ungrouped port) rather than treated as an error.
 */
const BRACKET_PAIRS: [string, string][] = [
  ["(", ")"],
  ["{", "}"],
  ["[", "]"],
];

function unwrap(line: string): string {
  for (const [open, close] of BRACKET_PAIRS) {
    if (line.startsWith(open) && line.endsWith(close)) return line.slice(1, -1);
  }
  return line;
}

export interface ParsedGroups {
  assignments: Record<string, GroupAssignment>;
  /** Ids named in the text that aren't a port on this edge — surfaced so a
   *  typo is visible, but never blocking. */
  unknownIds: string[];
}

export function parseGroupSyntax(text: string, knownIds: string[]): ParsedGroups {
  const known = new Set(knownIds);
  const assignments: Record<string, GroupAssignment> = {};
  const unknownIds: string[] = [];
  const lines = text
    .split("\n")
    .map((line) => unwrap(line.trim()).trim())
    .filter(Boolean);

  lines.forEach((line, lineIndex) => {
    const members = line
      .split(",")
      .map((m) => m.trim())
      .filter(Boolean);
    if (members.length < 2) return;
    const groupId = `g${lineIndex}`;
    members.forEach((id, order) => {
      if (!known.has(id)) {
        unknownIds.push(id);
        return;
      }
      assignments[id] = { groupId, order };
    });
  });

  return { assignments, unknownIds };
}

export function groupingSetFromText(text: string, knownIds: string[]): { set: GroupingSetDef; unknownIds: string[] } {
  const { assignments, unknownIds } = parseGroupSyntax(text, knownIds);
  return {
    set: { id: "text", label: "Text groups", description: "Typed on the edge itself.", assignments },
    unknownIds,
  };
}

