  DELAY_DOT_PX,
  DIR_VECTOR,
  LABEL_POSITION_DEFAULT,
  PATH_LENGTH_UNITS,
  TRACE_DIRS,
  asyncDashOffsetForLength,
  clampLabelPosition,
  pointAtFraction,
  polylineLength,
  safeElementId,
  splitDashArrays,
  type Point,
  type TraceDir,
  type TraceMarkerEnd,
  type TraceRouting,
  type TraceTerminalSpec,
  type TraceVariant,
} from "./trace.layout";
import { routeTrace, type DirectRouting, type TraceCurve } from "./trace.routing";
import type { TraceBend } from "./trace.bends";
import {
  elbowPath,
  routeElbow,
  type ElbowPin,
  type ElbowRect,
  type ElbowRouteOptions,
  type ElbowRoutingObstacle,
} from "./elbow/index";
import { elbowInputFromTerminals, routePoints } from "./elbow/traceContract";
import { TraceTerminal } from "./traceTerminal";

/** The transparent hit path's stroke width. Wider than the 2px visible
 * line by design: the line is the thing you SEE, this is the thing you can
 * plausibly double-click. Same trick, same reason, as React Flow's
 * `BaseEdge` interaction path. */
export const TRACE_HIT_STROKE_PX = 12;

// WHY `points` is omitted from the `<g>` props as well as `id`: React's
// `SVGProps` gives EVERY svg element the `points` attribute (typed
// `string`, for `<polyline>`/`<polygon>`), so the `Point[]` prop below is a
// genuine name collision — caught by `tsc`, not papered over with a cast. A
// `<g>` has no `points` attribute to lose.
export interface TraceProps extends Omit<ComponentProps<"g">, "id" | "points"> {
  /**
   * The host's own id for this trace (React Flow's edge `id`, a tldraw
   * shape's `id`) — hex-encoded into the marker's DOM id
   * (`safeElementId("bbox-trace-head", id)`, `trace.layout.ts`) so
   * multiple Trace instances on one page never collide. See that
   * function's own doc comment for three rounds of adversarial review this
   * genuinely needed. Deliberately NOT generated internally (no
   * `useId()`): an id `TraceBody` invents itself would be identity this
   * component doesn't own. Matches SystemSketch's own precedent — its
   * marker id is `systemsketch-slanted-arrowhead-${shape.id}`, derived
   * from the real shape, never generated.
   */
  id: string;
  /** The finished path — a host computes this. Trace never derives its own points. */
  path: string;
  /**
   * Arc length of `path`, for dash-phase math (async centering, the
   * delayed split). NOT the straight endpoint distance — a curve is longer
   * than its chord, which is the report's own warning. The host-agnostic
   * way to get it for a curve is `SVGPathElement.getTotalLength()` on the
   * mounted path.
   */
  length?: number;
  /**
   * The polyline `path` was built from, when the caller HAS exact vertices
   * (every routing but `curved`). Two jobs, neither of them derivation:
   * it supplies `length` when `length` is omitted (removing the
   * chord-vs-arc footgun above at the call site), and it is the array a
   * host hands `TraceBadge` for `fractionNearest`/`pointAtFraction` (P4).
   * `length` wins when both are given.
   */
  points?: readonly Point[];
  variant?: TraceVariant;
  /** Any CSS colour. Replaces the donor's governed `strokeColor` token
   * (see this file's header). The marker inherits it via `context-stroke`,
   * so there is never a second colour derivation. */
  color?: string;
  /** Marching-ants, `variant:"data"` only, opt-in. */
  animated?: boolean;
  /** `variant:"delayed"` only — paints solid up to `labelPosition`, dotted
   * after it, so a label can sit in the seam. */
  splitAtLabel?: boolean;
  /** Where 0..1 along the path the delayed split lands — clamped to
   * 0.05..0.95 regardless of what's passed (`clampLabelPosition`). */
  labelPosition?: number;
  markerEnd?: TraceMarkerEnd;
  strokeWidth?: number;
  vectorEffect?: "non-scaling-stroke";
  /** Mount the invisible 12px hit path. Off by default: a Trace that
   * nothing listens to should not be silently eating pointer events from
   * whatever sits under it. */
  interactive?: boolean;
}

export interface TraceStrokeStyle {
  strokeDasharray?: string;
  strokeDashoffset?: number;
  strokeLinecap: "round" | "butt";
  /** Marching-ants class — DATA ONLY, never applied as a side effect by
   * this function. The caller puts it on the rendered element's
   * `className`, never inside `style`. */
  className?: string;
}

/**
 * Pure — no DOM. Dash MECHANICS only (pattern, phase/offset, the
 * marching-ants class NAME), never colour: colour is a plain `color` prop
 * here, resolved nowhere. An adapter calls this directly when assembling
 * React Flow's own `BaseEdge` `style` prop for the single-stroke variants.
 */
export function traceStrokeStyle(
  variant: TraceVariant,
  length: number,
  animated = false,
): TraceStrokeStyle {
  if (variant === "async") {
    return {
      strokeDasharray: ASYNC_PACKET_DASHARRAY,
      strokeDashoffset: asyncDashOffsetForLength(length),
      strokeLinecap: "butt",
    };
  }
  if (variant === "delayed") {
    return {
      strokeDasharray: `${DELAY_DOT_PX} ${DELAY_DOT_GAP_PX}`,
      strokeLinecap: "round",
    };
  }
  const marching = animated;
  return {
    strokeDasharray: marching ? DATA_MARCH_DASHARRAY : undefined,
    strokeLinecap: marching ? "butt" : "round",
    className: marching ? DATA_MARCH_CLASS : undefined,
  };
}

/** Marker geometry lives once, referenced by every variant that draws a
 * head — the open two-stroke chevron `SlantedArrowBody` established.
 * `context-stroke` (a real SVG2 paint keyword; broad Chromium/Firefox
 * support per MDN, NOT YET Safari — there the marker falls back to its own
 * unspecified default stroke rather than erroring, a degraded look, not a
 * broken one) makes it inherit whatever stroke paints the line beside it,
 * so it never needs a second colour derivation or a duplicate marker per
 * colour. */
export function TraceMarkerDef({ id }: { id: string }) {
  return (
    <marker
      data-slot="trace-marker"
      id={id}
      viewBox="0 0 10 10"
      refX="8.5"
      refY="5"
      markerWidth="7"
      markerHeight="7"
      orient="auto"
      overflow="visible"
    >
      <path
        data-slot="trace-marker-head"
        d="M 1 1 L 9 5 L 1 9"
        fill="none"
        stroke="context-stroke"
        strokeWidth={2}
        strokeLinejoin="round"
        strokeLinecap="round"
      />
    </marker>
  );
}

/**
 * The paint — one visible `<path>` for `data`/`async`, two for a `delayed`
 * trace with `splitAtLabel`, plus the optional invisible hit path. Zero
 * imports of any canvas engine.
 */
export function TraceBody({
  id,
  path,
  length,
  points,
  variant = "data",
  color = "var(--muted-foreground)",
  animated = false,
  splitAtLabel = false,
  labelPosition = LABEL_POSITION_DEFAULT,
  markerEnd = "arrow",
  strokeWidth = 2,
  vectorEffect,
  interactive = false,
  className,
  ...props
}: TraceProps) {
  const markerId = safeElementId("bbox-trace-head", id);
  const hasMarker = markerEnd !== "none";
  const markerAttr = hasMarker ? `url(#${markerId})` : undefined;
  const resolvedLength = length ?? (points ? polylineLength(points) : 0);

  const defs = hasMarker ? (
    <defs data-slot="trace-defs">
      <TraceMarkerDef id={markerId} />
    </defs>
  ) : null;

  // Painted FIRST so the visible line always sits on top of it. It is
  // transparent, not `opacity:0` — a transparent stroke still hit-tests
  // with `pointer-events: stroke`, which is the entire point.
  const hit = interactive ? (
    <path
      data-slot="trace-hit"
      d={path}
      fill="none"
      stroke="transparent"
      strokeWidth={TRACE_HIT_STROKE_PX}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ pointerEvents: "stroke" }}
    />
  ) : null;

  if (variant === "delayed" && splitAtLabel) {
    const dash = splitDashArrays(resolvedLength, clampLabelPosition(labelPosition));
    return (
      <g
        data-slot="trace"
        data-variant={variant}
        data-split="true"
        className={cn(className)}
        {...props}
      >
        {defs}
        {hit}
        <path
          data-slot="trace-line"
          data-trace-segment="before"
          d={path}
          pathLength={PATH_LENGTH_UNITS}
          fill="none"
          stroke={color}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth={strokeWidth}
          strokeDasharray={dash.before}
          vectorEffect={vectorEffect}
        />
        <path
          data-slot="trace-line"
          data-trace-segment="after"
          d={path}
          pathLength={PATH_LENGTH_UNITS}
          fill="none"
          stroke={color}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth={strokeWidth}
          strokeDasharray={dash.after}
          vectorEffect={vectorEffect}
          markerEnd={markerAttr}
        />
      </g>
    );
  }

  const dashStyle = traceStrokeStyle(variant, resolvedLength, animated);
  return (
    <g
      data-slot="trace"
      data-variant={variant}
      data-animated={animated || undefined}
      className={cn(className)}
      {...props}
    >
      {defs}
      {hit}
      <path
        data-slot="trace-line"
        data-trace-segment="whole"
        d={path}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap={dashStyle.strokeLinecap}
        strokeLinejoin="round"
        strokeDasharray={dashStyle.strokeDasharray}
        strokeDashoffset={dashStyle.strokeDashoffset}
        vectorEffect={vectorEffect}
        className={dashStyle.className}
        markerEnd={markerAttr}
      />
    </g>
  );
}

/* ==========================================================================
 * Trace — the wrapper (docs/TRACE-PLAN.md P6)
 *
 * `TraceBody` above is props-in, DOM-out and derives nothing. `Trace` is the
 * one place in this app allowed to derive: it takes the two frozen
 * `TraceTerminalSpec`s and a `routing` kind, asks P2 (`routeTrace`) or P3
 * (`routeElbow`) for the geometry, and paints the line plus the two terminal
 * glyphs. Everything below is net-new; nothing here is a port.
 * ========================================================================== */

/**
 * How far short of a terminal's CENTRE the wire stops, along the flow.
 *
 * WHY the wire cannot simply end at `{x, y}`: the glyph's disc is opaque
 * (deliberately — see `traceTerminal.tsx`) with r=9, and the chevron marker
 * reaches ~12px back from the path's end. A wire drawn to the exact centre
 * therefore loses BOTH its arrowhead and its last 9px under the disc.
 *
 * `TraceElbow.stories.tsx` computes the identical pull-back inline
 * (`routeStart`/`routeEnd`, `TERMINAL_GAP = 16`) because it was written
 * before this wrapper existed. That file is another lane's and is left
 * alone; the two agreeing is asserted in `TracePolarity.stories.tsx` rather
 * than assumed, so the duplication cannot drift silently.
 */
export const TRACE_TERMINAL_GAP = 16;

/** How many points a curved route is sampled into when a caller asks for a
 * polyline (`onGeometry`). A Bezier genuinely has no vertices — this is a
 * SAMPLE, and it is named one. */
export const TRACE_CURVE_SAMPLES = 64;

/** Everything `Trace` needs to compute a route, with no React in sight — so
 * a play function can ask for the same geometry the component drew without
 * rendering anything. */
export interface TraceRouteRequest {
  from: TraceTerminalSpec;
  to: TraceTerminalSpec;
  routing: TraceRouting;
  /** Pull-back at each end; defaults to {@link TRACE_TERMINAL_GAP}. */
  gap?: number;
  /** `straight` / `curved`: the dragged centre control point. */
  curve?: TraceCurve | null;
  /** `slanted`: where along the departure axis the bend sits, 0..1. */
  slantT?: number | null;
  /** `straight` only: N intermediate control points, chord-relative
   * (docs/TRACE-CONTROL-POINTS-PLAN.md D1/D2). Ignored by every other
   * routing — see `trace.routing.ts`'s `TraceRouteOptions.bends`. */
  bends?: readonly TraceBend[] | null;
  /** `elbow`: persisted bends. */
  pins?: readonly ElbowPin[];
  /** `elbow`: keep-outs. A story fixture IS this list. */
  obstacles?: readonly ElbowRoutingObstacle[];
  fromBox?: ElbowRect | null;
  toBox?: ElbowRect | null;
  elbowOptions?: Partial<ElbowRouteOptions>;
}

export interface TraceGeometry {
  routing: TraceRouting;
  /** The SVG `d` handed to `TraceBody`. */
  path: string;
  /**
   * Exact vertices, or `null` for a curve — a cubic HAS no vertices, and
   * `routeTrace` already says so rather than inventing some. A caller that
   * needs a polyline for a curve gets a SAMPLED one from `onGeometry`,
   * measured off the mounted `SVGPathElement`, and it is labelled `sampled`.
   */
  points: Point[] | null;
  /**
   * Arc length. Exact for `straight`/`slanted`. For `elbow` this is the
   * ROUTE's length, which slightly overstates the DRAWN length because
   * `elbowPath` rounds every corner (a rounded corner is shorter than the
   * two half-segments it replaces — at most `(2 - pi/2) * r` ≈ 3.4px per
   * corner at r=8). Stated rather than silently accepted: it moves an async
   * dash phase by a few pixels and nothing else. `0` for an unmeasured
   * curve, replaced by the real `getTotalLength()` once mounted.
   */
  length: number;
  /** The exit sides the ROUTER was actually given — one derivation, read
   * back rather than recomputed (see the elbow branch's note). */
  sides: { start: TraceDir; end: TraceDir };
  /** Where a centre control point sits for this routing. */
  waypoint: Point;
  /** The route's real endpoints: the terminals pulled back by `gap`. */
  start: TraceTerminalSpec;
  end: TraceTerminalSpec;
}

/** The route's start: `gap` along the flow, out of the glyph. */
export function traceRouteStart(from: TraceTerminalSpec, gap: number): TraceTerminalSpec {
  return {
    x: from.x + DIR_VECTOR[from.dir].x * gap,
    y: from.y + DIR_VECTOR[from.dir].y * gap,
    dir: from.dir,
  };
}

/**
 * The route's end: `gap` BEHIND the target, measured along the direction of
 * travel, so the arrowhead sits in the gap pointing at the glyph. For
 * `dir: "left"` that puts the wire's last point to the RIGHT of the
 * terminal — the wrap-around case, not a sign error.
 */
export function traceRouteEnd(to: TraceTerminalSpec, gap: number): TraceTerminalSpec {
  return {
    x: to.x - DIR_VECTOR[to.dir].x * gap,
    y: to.y - DIR_VECTOR[to.dir].y * gap,
    dir: to.dir,
  };
}

/**
 * The one dispatch that spans both routing lanes. Pure: no React, no DOM.
 *
 * WHY it lives here and not in `trace.routing.ts`: that module's header
 * states, and enforces with its `DirectRouting` type, that a 450-line
 * geometry file has no business importing 2,500 lines of A*. The wrapper is
 * the seam where the two legitimately meet, so the import weight lands on
 * the component that actually needs both.
 */
export function traceGeometry(request: TraceRouteRequest): TraceGeometry {
  const gap = request.gap ?? TRACE_TERMINAL_GAP;
  return traceGeometryBetween(
    traceRouteStart(request.from, gap),
    traceRouteEnd(request.to, gap),
    request,
  );
}

/**
 * The routing half on its own, over endpoints that are ALREADY pulled back.
 *
 * WHY this is a separate function and not an implementation detail inlined
 * into `traceGeometry`: the gap pull-back consumes `dir` too — moving the
 * endpoint 16px along the flow — so a naive "permute `to.dir` and see if the
 * path changes" test answers TRUE for every routing, `straight` included,
 * because the endpoint moved. Measured before it was believed (2026-09-17):
 * with the pull-back folded in, `straight` reported `readsTo = true`, which
 * flatly contradicts docs/TRACE-PLAN.md's "straight is tangent-blind
 * everywhere" and would have shipped a gallery captioning a plain chord as
 * tangent-aware. `traceReadsTangent` therefore pulls back ONCE with the
 * request's real dirs and permutes only the `dir` the ROUTER sees, which is
 * the question actually being asked.
 */
export function traceGeometryBetween(
  start: TraceTerminalSpec,
  end: TraceTerminalSpec,
  request: Omit<TraceRouteRequest, "from" | "to" | "gap">,
): TraceGeometry {
  if (request.routing === "elbow") {
    const input = elbowInputFromTerminals({
      from: start,
      to: end,
      ...(request.obstacles ? { obstacles: request.obstacles } : {}),
      fromBox: request.fromBox ?? null,
      toBox: request.toBox ?? null,
      ...(request.pins ? { pins: request.pins } : {}),
      ...(request.elbowOptions ? { options: request.elbowOptions } : {}),
    });
    const route = routeElbow(input);
    const points = routePoints(route);
    return {
      routing: "elbow",
      path: elbowPath(route),
      points,
      length: polylineLength(points),
      // Read back off the input the ROUTER was actually given, never
      // re-derived from the terminals. Mutation testing (2026-09-17) found
      // why that distinction has teeth: an earlier version computed `sides`
      // here with its own `traceSideOf` call, and breaking THAT copy —
      // dropping the `OPPOSITE_DIR` flip at the `to` end — changed nothing
      // anyone could observe, because the router had already derived the
      // real sides inside `elbowInputFromTerminals`. A second derivation of
      // one number is how the two stop agreeing; there is now only one.
      sides: { start: input.start.side, end: input.end.side },
      // The middle of the polyline: for an elbow the "centre control point"
      // is a PIN, not an offset, so the honest waypoint is just the route's
      // own midpoint rather than a number a pin could be read back out of.
      // Shared with `straight`'s own polyline midpoint (D2 of
      // docs/TRACE-CONTROL-POINTS-PLAN.md) via `trace.layout.ts`'s
      // `pointAtFraction` — this file used to carry a second, near-identical
      // restatement of that same arc-length walk (`pointAtPolylineFraction`
      // below), which is exactly the kind of drift the plan calls out: "do
      // not invent a second rule." One function now serves both branches.
      waypoint: pointAtFraction(points, 0.5),
      start,
      end,
    };
  }

  const route = routeTrace(request.routing as DirectRouting, start, end, {
    curve: request.curve ?? null,
    slantT: request.slantT ?? null,
    bends: request.bends ?? null,
  });
  return {
    routing: route.routing,
    path: route.path,
    points: route.points,
    length: route.points ? polylineLength(route.points) : 0,
    sides: route.sides,
    waypoint: route.waypoint,
    start,
    end,
  };
}

/**
 * Does `routing` actually READ the flow tangent at `end`, for THIS request?
 *
 * MEASURED, never tabled. `trace.routing.ts` defines "blind" falsifiably —
 * "the returned geometry is INVARIANT under changing that end's `dir`" — so
 * this permutes that end's `dir` through all four values with every other
 * input held fixed and counts distinct `path` strings. One distinct path
 * means the function never looked; more than one means it did.
 *
 * WHY this and not `honorsTangent` from `trace.routing.ts`:
 *
 *  1. That table has no `elbow` row, by its own deliberate choice ("this
 *     lane asserting something about a router it does not own"). This
 *     covers elbow for free, because it never names a routing.
 *  2. The table is GEOMETRY-INDEPENDENT and therefore wrong on a degenerate
 *     chord: `TRACE_ROUTING_TANGENTS.slanted.from` is a flat `"honored"`,
 *     but `getSlantedArrowPoints` returns `[start, end]` — ignoring the
 *     departure entirely — the moment `|dx|` or `|dy|` drops under 0.001.
 *     A gallery built on the natural axis-aligned layout would have
 *     captioned a plain chord "leaves along from.dir". Measuring instead of
 *     asking cannot make that mistake, and `Degenerate` renders exactly
 *     that case to prove the difference is real rather than theoretical.
 *
 * NOT the whole story on its own: reading a tangent and ARRIVING along it
 * are two different facts, and a chord can arrive along `to.dir` by
 * coincidence without ever reading it (the plan's own "chord happens to
 * align"). `TracePolarity.stories.tsx` measures the arrival angle off the
 * rendered path and requires BOTH.
 */
export function traceReadsTangent(request: TraceRouteRequest, end: "from" | "to"): boolean {
  const gap = request.gap ?? TRACE_TERMINAL_GAP;
  // Pulled back ONCE, with the request's real dirs, and then held fixed —
  // see `traceGeometryBetween` for why folding the pull-back into the
  // permutation makes every routing look tangent-aware.
  const start = traceRouteStart(request.from, gap);
  const end_ = traceRouteEnd(request.to, gap);
  const paths = new Set(
    TRACE_DIRS.map(
      (dir) =>
        traceGeometryBetween(
          end === "from" ? { ...start, dir } : start,
          end === "to" ? { ...end_, dir } : end_,
          request,
        ).path,
    ),
  );
  return paths.size > 1;
}

// WHY `from` and `to` are omitted from the `<g>` props (the same collision
// `TraceBody` hit with `points`, and caught the same way — by `tsc`, not by a
// cast): React's `SVGProps` gives every SVG element the SMIL animation
// attributes `from`/`to`, typed `string | number`. The two terminal props
// below are the genuine names for this component, so the animation
// attributes are what give way.
export interface TraceRouteProps
  extends Omit<ComponentProps<"g">, "id" | "from" | "to">,
    Omit<TraceRouteRequest, "routing"> {
  /** Host id — hex-encoded into the marker id, exactly as `TraceBody` says. */
  id: string;
  /** Defaults to `curved` — the kit's own default, and the only one of the
   * four that honours both flow tangents with no control point touched. */
  routing?: TraceRouting;
  variant?: TraceVariant;
  color?: string;
  animated?: boolean;
  splitAtLabel?: boolean;
  labelPosition?: number;
  markerEnd?: TraceMarkerEnd;
  strokeWidth?: number;
  vectorEffect?: "non-scaling-stroke";
  interactive?: boolean;
  /** Draw the two endpoint glyphs. On by default — `Trace` is "the whole
   * thing"; a host with real `Port`s passes `false`. */
  terminals?: boolean;
  terminalRadius?: number;
  terminalColor?: string;
  /** Fired with the resolved geometry after layout, so a host can hand the
   * polyline to `TraceBadge`. For a curve the `points` handed over are
   * SAMPLED off the mounted path (`TRACE_CURVE_SAMPLES`) and `length` is the
   * real `getTotalLength()`. */
  onGeometry?: (geometry: TraceGeometry) => void;
  curveSamples?: number;
}

/**
 * Two terminal specs and a routing kind in, the whole drawn thing out.
 *
 * The curve measurement, and why it needs a layout effect at all: a cubic's
 * arc length is not available from the control points without an integral,
 * and the browser already computes it exactly — `getTotalLength()`. So a
 * curved trace paints once with `length: 0` (which changes nothing for
 * `data`, and only the dash PHASE for `async` on a path shorter than one
 * 74px cadence), then re-renders with the measured value. Stated plainly
 * because "one extra render on curves" is a real cost, not an invisible one.
 */
export function Trace({
  from,
  to,
  routing = "curved",
  gap,
  curve,
  slantT,
  bends,
  pins,
  obstacles,
  fromBox,
  toBox,
  elbowOptions,
  id,
  variant = "data",
  color,
  animated,
  splitAtLabel,
  labelPosition,
  markerEnd = "arrow",
  strokeWidth,
  vectorEffect,
  interactive,
  terminals = true,
  terminalRadius,
  terminalColor,
  onGeometry,
  curveSamples = TRACE_CURVE_SAMPLES,
  className,
  ...props
}: TraceRouteProps) {
  // Geometry AND per-end arrow fidelity, derived together — see
  // `TraceTerminal`'s own `showDirection` doc for the underlying claim.
  // WHY this lives here rather than being left to each caller: `Trace` is
  // already the one place that turns a routing KIND into geometry (this
  // file's own P6 header), so it is the one place that can honestly answer
  // "does the picture I'm about to draw actually depend on this end's
  // dir" without a caller re-deriving `traceReadsTangent` itself (which
  // would either duplicate this call or, worse, hardcode routing names —
  // exactly the trap `TracePolarity.stories.tsx` documents at length).
  // Measured with `traceReadsTangent`, never read off a static per-routing
  // table: `routingTangents`'s own table is geometry-INDEPENDENT and wrong
  // on a bent curve or a degenerate slanted chord (see that function's doc
  // comment), and a terminal glyph that trusted the table over the actual
  // geometry would repeat the exact bug this component exists to fix.
  const { geometry, showFromDirection, showToDirection } = useMemo(() => {
    const request: TraceRouteRequest = {
      from,
      to,
      routing,
      gap,
      curve,
      slantT,
      bends,
      pins,
      obstacles,
      fromBox,
      toBox,
      elbowOptions,
    };
    return {
      geometry: traceGeometry(request),
      showFromDirection: traceReadsTangent(request, "from"),
      showToDirection: traceReadsTangent(request, "to"),
    };
  },
    // WHY the two terminals and `curve` are spread into scalars rather than
    // listed as objects: a caller writing `from={{ x, y, dir: "right" }}`
    // inline — which every story here does, and which is the natural way to
    // use this — would otherwise hand a fresh object identity on every render
    // and re-run the A* router each time. The elbow collections BELOW are
    // still compared by identity, because they have no fixed shape to spread;
    // a host that rebuilds its obstacle array every frame pays for a re-route
    // every frame, and that is the one perf footgun in this component.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      from.x, from.y, from.dir,
      to.x, to.y, to.dir,
      routing, gap,
      curve?.dx, curve?.dy, slantT,
      bends, pins, obstacles, fromBox, toBox, elbowOptions,
    ],
  );

  const hostRef = useRef<SVGGElement | null>(null);
  const [measuredLength, setMeasuredLength] = useState<number | null>(null);
  // The callback in a ref so a caller passing an inline arrow does not make
  // the effect below re-fire on every render.
  const onGeometryRef = useRef(onGeometry);
  onGeometryRef.current = onGeometry;

  useLayoutEffect(() => {
    const host = hostRef.current;
    const line = host?.querySelector<SVGPathElement>('[data-slot="trace-line"]') ?? null;
    let resolved = geometry;
    if (geometry.points === null && line) {
      const total = line.getTotalLength();
      const sampled: Point[] = [];
      for (let i = 0; i <= curveSamples; i += 1) {
        const p = line.getPointAtLength((total * i) / curveSamples);
        sampled.push({ x: p.x, y: p.y });
      }
      resolved = { ...geometry, length: total, points: sampled };
      setMeasuredLength(total);
    } else {
      setMeasuredLength(null);
    }
    onGeometryRef.current?.(resolved);
  }, [geometry, curveSamples]);

  return (
    <g
      data-slot="trace-route"
      data-routing={geometry.routing}
      data-side-start={geometry.sides.start}
      data-side-end={geometry.sides.end}
      ref={hostRef}
      className={cn(className)}
      {...props}
    >
      <TraceBody
        id={id}
        path={geometry.path}
        length={measuredLength ?? geometry.length}
        points={geometry.points ?? undefined}
        variant={variant}
        color={color}
        animated={animated}
        splitAtLabel={splitAtLabel}
        labelPosition={labelPosition}
        markerEnd={markerEnd}
        strokeWidth={strokeWidth}
        vectorEffect={vectorEffect}
        interactive={interactive}
      />
      {terminals ? (
        <>
          <TraceTerminal
            data-end="from"
            x={from.x}
            y={from.y}
            dir={from.dir}
            radius={terminalRadius}
            color={terminalColor}
            showDirection={showFromDirection}
          />
          <TraceTerminal
            data-end="to"
            x={to.x}
            y={to.y}
            dir={to.dir}
            radius={terminalRadius}
            color={terminalColor}
            showDirection={showToDirection}
          />
        </>
      ) : null}
    </g>
  );
}

"use client";

// src/components/traceTerminal.tsx — NET-NEW (docs/TRACE-PLAN.md P1). Not a
// port: neither `packages/bbox-ui` nor SystemSketch has a terminal glyph.
//
// WHY this exists at all, and why it is NOT a `Port`: Zach's explicit
// reversal — "Let's not use real ports. We can just draw a circle with an
// arrow inside that shows the polarity... they just take an xy position and
// a polarity, and input/output direction." These are ILLUSTRATION props for
// the trace galleries, so nothing here imports `port.tsx`, and a real board
// would mount a real `Port` instead. Keeping them separate is what stops a
// story fixture from quietly becoming a second, competing port component.
//
// WHY `{x, y, dir}` and no polarity prop: (face, polarity) -> flow tangent
// is 2-to-1, so the eight pairs quotient to four glyphs — Zach's own
// correction, "really 4 options not 8 because top input is the same as
// bottom output." The full argument, and the `side(from)`/`side(to)`
// derivation that keeps the ROUTE knowing which end is which, live on
// `TraceDir` in `./trace.layout.ts`. The arrowhead that distinguishes the
// ends is painted by the trace (`markerEnd` at the `to` end), never here.

import type { ComponentProps } from "react";

import { cn } from "../lib/utils";
import { DIR_ROTATION, type TraceDir } from "./trace.layout";

/** The glyph's ring radius in user units. 9 keeps it a touch smaller than
 * `Port`'s `md` dot so a terminal never reads as a port. */
export const TRACE_TERMINAL_RADIUS = 9;
export const TRACE_TERMINAL_RING_PX = 2;

/**
 * The arrow inside the ring, authored pointing +x (i.e. `dir: "right"`) and
 * rotated by `DIR_ROTATION`. Expressed as fractions of the radius so the
 * glyph scales as one piece.
 *
 * The tail deliberately stops SHORT of where the tip reaches (0.40r behind
 * the centre vs 0.50r ahead) for LEGIBILITY ONLY: at an 18px ring a shaft
 * centred on the disc reads as a plus sign, and the short tail biases the
 * whole mark forward so it reads as travelling.
 *
 * It is NOT what makes the glyph measurably directional — mutation-testing
 * this (2026-09-17, tail 0.40r -> 0.50r) left `Trace.stories.tsx` green,
 * because the HEAD alone already pulls the arc-length centroid ~1.4px onto
 * the `dir` side. The head is the load-bearing part of that measurement;
 * deleting it drops the centroid offset under the story's 1px floor and
 * turns the suite red. Recorded so a future tidy-up does not "simplify" the
 * head away on the theory that the shaft carries the direction.
 */
function arrowPath(radius: number): string {
  const tail = -0.4 * radius;
  const tip = 0.5 * radius;
  const barbX = 0.075 * radius;
  const barbY = 0.36 * radius;
  return `M ${tail} 0 L ${tip} 0 M ${barbX} ${-barbY} L ${tip} 0 L ${barbX} ${barbY}`;
}

export interface TraceTerminalProps extends Omit<ComponentProps<"g">, "x" | "y"> {
  x: number;
  y: number;
  /** The flow tangent — the direction data travels THROUGH this point.
   * NOT a face and NOT a polarity; see `TraceDir`. */
  dir: TraceDir;
  radius?: number;
  /** Any CSS colour. Defaults to the accent `Port` already uses for
   * `wired` (docs/TRACE-PLAN.md D8: the screenshot's amber IS this repo's
   * orange, so no new token). */
  color?: string;
  /** What fills the disc. Opaque on purpose — an opaque disc hides the
   * trace's own stroke running underneath it, so the line reads as
   * arriving AT the terminal rather than through it. */
  fill?: string;
  /**
   * Draw the arrow that claims this end's flow tangent. Defaults to
   * `true` so every existing caller is unaffected.
   *
   * WHY this exists: `dir` is a fact about the TERMINAL — it is always
   * well-defined — but the arrow is a claim about the ROUTE, namely that
   * the painted path actually leaves or arrives along it. `straight` and
   * `slanted` don't honor that claim at every end (`TRACE_ROUTING_TANGENTS`
   * / `routingTangents` in `trace.routing.ts` — the fidelity is per END and
   * per ROUTING, not a blanket "these two kinds never show polarity": a
   * `slanted` trace honors its SOURCE and is blind only at its target). A
   * caller whose routing doesn't read this end's `dir` passes `false`
   * rather than let the glyph assert a polarity the geometry ignores —
   * this was Zach's own correction on the `TracePolarity` gallery, which
   * drew an arrow on every terminal regardless of whether anything
   * downstream ever looked at it.
   *
   * The ring's radius and centre never move when this is `false` — only
   * the arrow `<path>` is omitted — so a blind and an honored terminal
   * still line up size-for-size in a gallery row.
   */
  showDirection?: boolean;
}

/**
 * An SVG `<g>` — mount it inside an `<svg>`, positioned by its own
 * `x`/`y`, not by CSS. Renders nothing interactive: no pointer handlers, no
 * hit halo, no state. A story that wants a terminal to be draggable adds
 * that itself.
 */
export function TraceTerminal({
  x,
  y,
  dir,
  radius = TRACE_TERMINAL_RADIUS,
  color = "var(--bbox-primary, var(--primary))",
  fill = "var(--card)",
  showDirection = true,
  className,
  ...props
}: TraceTerminalProps) {
  return (
    <g
      data-slot="trace-terminal"
      data-dir={dir}
      transform={`translate(${x} ${y}) rotate(${DIR_ROTATION[dir]})`}
      className={cn(className)}
      {...props}
    >
      <circle
        data-slot="trace-terminal-ring"
        cx={0}
        cy={0}
        r={radius}
        fill={fill}
        stroke={color}
        strokeWidth={TRACE_TERMINAL_RING_PX}
      />
      {showDirection ? (
        <path
          data-slot="trace-terminal-arrow"
          d={arrowPath(radius)}
          fill="none"
          stroke={color}
          strokeWidth={Math.max(1, radius * 0.2)}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      ) : null}
    </g>
  );
}

"use client";

// src/components/wireLayer.tsx — `WireLayer`: paints a `Wire[]` as `Trace`s
// between two Blocks' real, measured Port dots (docs/BLOCK-PORT-EDGES-PLAN.md
// §5, phase B1). `WireLayerProps` is the frozen contract the plan declared
// before this file existed, so B2's async gallery could code against it
// while this lane was still building it.
//
// WireLayer never invents a point. It resolves each `WireEnd` to a rendered
// dot — `[data-port-id]` inside `[data-block-id]`, falling back to a
// collapsed stand-in dot whose `data-collapsed-ports` names the id (the same
// dot a Block flips to in simple view — no wire data changes, only
// measurement) — reads its centre with `getBoundingClientRect` (app-level
// measurement, the same D8 legality `blockPort.tsx`'s own band-measuring
// already relies on), and hands the two points to `Trace`. An end that
// cannot be found — a wire into a child whose block is not expanded — is
// skipped, not guessed at, and its wire id is stamped onto the layer's own
// `data-unresolved-wires`, matching the donor's rule that only expanded
// blocks can show children.
//
// WHY the layer paints ABOVE every Block (D-B1, reversing the donor's
// `keepConnectionsAtBottom`): a wire attaches to a dot that already sits on
// a wall painting above the block's own card (`blockPort.tsx`'s own D-B1
// note) — a wire painting under the block would have its whole approach to
// that dot swallowed by the card. `pointer-events: none` on the SVG root
// keeps the layer from stealing drag/click from anything under it; `Trace`'s
// own `interactive` hit path is exactly the opt-back-in a host that wants
// one would reach for, left off here on purpose.
//
// WHY there is no polarity prop anywhere here (the plan's "8-vs-4"
// resolution): a rail's own `data-edge` attribute already says everything a
// terminal spec needs, because `BlockSide` ("top"|"right"|"bottom"|"left")
// is already the exact same union as `TraceDir` — `from` leaves along the
// FROM port's own wall, `to` arrives travelling AGAINST the TO port's wall
// (`OPPOSITE_DIR`).
import { useLayoutEffect, useState, type RefObject } from "react";

import type { BlockSide } from "./port.layout";
import { Trace } from "./trace";
import { OPPOSITE_DIR, type TraceDir, type TraceTerminalSpec } from "./trace.layout";
import { fanWires, type Wire, type WireEnd } from "./wiring";

/* ------------------------------------------------------------------ */
/* The frozen surface (plan §5)                                        */
/* ------------------------------------------------------------------ */

export interface WireLayerProps {
  wires: Wire[];
  /** The fixture element whose coordinate space the layer fills; the layer
   *  is an absolutely-positioned SVG inset 0 inside it, rendered LAST. */
  containerRef: RefObject<HTMLElement | null>;
  /** Re-measure signal — bump when items/views change. */
  layoutKey?: unknown;
}

/* ------------------------------------------------------------------ */
/* Resolving a WireEnd to a dot, and a dot to a terminal spec           */
/* ------------------------------------------------------------------ */

/** `[data-port-id]` inside `[data-block-id]` first; a collapsed stand-in dot
 *  whose `data-collapsed-ports` list contains the id otherwise. Both
 *  attributes are stamped by `blockPort.tsx`'s rail fill, never by this
 *  file — `WireLayer` only reads DOM another component already wrote. */
function resolveDot(container: HTMLElement, end: WireEnd): HTMLElement | null {
  const block = container.querySelector<HTMLElement>(`[data-block-id="${end.blockId}"]`);
  if (!block) return null;
  const direct = block.querySelector<HTMLElement>(`[data-port-id="${end.portId}"]`);
  if (direct) return direct;
  for (const collapsed of block.querySelectorAll<HTMLElement>("[data-collapsed-ports]")) {
    const members = (collapsed.getAttribute("data-collapsed-ports") ?? "").split(",").map((id) => id.trim());
    if (members.includes(end.portId)) return collapsed;
  }
  return null;
}

/** The `BlockSide` a resolved dot's own rail is mounted on. A straight read,
 *  not a lookup table — `BlockSide` and `TraceDir` are already the same four
 *  strings, so the rail's own `data-edge` attribute IS the face normal. */
function railEdgeOf(dot: HTMLElement): BlockSide | null {
  const edge = dot.closest<HTMLElement>('[data-slot="block-port-rail"]')?.getAttribute("data-edge");
  return edge === "top" || edge === "right" || edge === "bottom" || edge === "left" ? edge : null;
}

function centreOf(dot: HTMLElement, containerRect: DOMRect): { x: number; y: number } {
  const rect = dot.getBoundingClientRect();
  return { x: rect.left + rect.width / 2 - containerRect.left, y: rect.top + rect.height / 2 - containerRect.top };
}

interface ResolvedWire {
  wire: Wire;
  from: TraceTerminalSpec;
  to: TraceTerminalSpec;
  curve: { dx: number; dy: number };
}

interface WireLayerState {
  resolved: ResolvedWire[];
  unresolvedIds: string[];
}

const EMPTY_STATE: WireLayerState = { resolved: [], unresolvedIds: [] };

function computeState(container: HTMLElement, wires: readonly Wire[]): WireLayerState {
  const containerRect = container.getBoundingClientRect();
  const fans = fanWires(wires);
  const resolved: ResolvedWire[] = [];
  const unresolvedIds: string[] = [];

  wires.forEach((wire, i) => {
    const fromDot = resolveDot(container, wire.from);
    const toDot = resolveDot(container, wire.to);
    const fromEdge = fromDot ? railEdgeOf(fromDot) : null;
    const toEdge = toDot ? railEdgeOf(toDot) : null;
    if (!fromDot || !toDot || !fromEdge || !toEdge) {
      unresolvedIds.push(wire.id);
      return;
    }
    const from: TraceTerminalSpec = { ...centreOf(fromDot, containerRect), dir: fromEdge as TraceDir };
    const to: TraceTerminalSpec = { ...centreOf(toDot, containerRect), dir: OPPOSITE_DIR[toEdge as TraceDir] };
    resolved.push({ wire, from, to, curve: fans[i].offset });
  });

  return { resolved, unresolvedIds };
}

/* ------------------------------------------------------------------ */
/* WireLayer                                                            */
/* ------------------------------------------------------------------ */

export function WireLayer({ wires, containerRef, layoutKey }: WireLayerProps) {
  const [state, setState] = useState<WireLayerState>(EMPTY_STATE);

  useLayoutEffect(() => {
    let cancelled = false;
    let frame: number | null = null;
    let observer: ResizeObserver | null = null;

    // Two F1-class races stack here (`BlockPortLane.stories.tsx` names the
    // first for the multi-line lane, and the same reasoning extends to the
    // second):
    //
    //  1. `containerRef` is owned by WHOEVER renders the fixture element
    //     (a story's own bench div, say) and WireLayer only reads it — a
    //     CHILD's layout effect can run before its PARENT's host ref has
    //     actually attached, so `containerRef.current` can be `null` on
    //     this very first pass even though the div is about to exist.
    //  2. Once the container itself exists, a `BlockPort`'s own rails (and
    //     every `[data-port-id]`/`[data-collapsed-ports]` dot on them)
    //     STILL do not exist on that same commit — they wait for
    //     `useBlockBands`'s own layout effect to measure the Block first,
    //     landing one render pass later. A `ResizeObserver` on the
    //     container does not catch it: adding position:absolute rails does
    //     not change the container's own box.
    //
    // `attach` retries every frame until the ref is real, then measures
    // immediately AND schedules one more deferred pass for (2), on top of
    // the steady-state `ResizeObserver`.
    const attach = () => {
      if (cancelled) return;
      const container = containerRef.current;
      if (!container) {
        frame = requestAnimationFrame(attach);
        return;
      }
      const measure = () => setState(computeState(container, wires));
      measure();
      frame = requestAnimationFrame(measure);
      observer = new ResizeObserver(measure);
      observer.observe(container);
    };
    attach();

    return () => {
      cancelled = true;
      if (frame !== null) cancelAnimationFrame(frame);
      observer?.disconnect();
    };
    // `wires` and `layoutKey` ARE the re-measure signal (plan §5): a caller
    // bumps `layoutKey` on anything that can move a dot without resizing the
    // container itself — a Block's view flipping between simple/port/
    // expanded, say, which changes where dots sit but not necessarily the
    // fixture's own outer box.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [containerRef, wires, layoutKey]);

  return (
    <svg
      data-slot="wire-layer"
      data-unresolved-wires={state.unresolvedIds.join(",")}
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, pointerEvents: "none", overflow: "visible" }}
    >
      {state.resolved.map(({ wire, from, to, curve }) => (
        // `id` is destructured out of both `Trace` and `TraceBody` (it feeds
        // the MARKER's own id, `safeElementId("bbox-trace-head", id)`) and
        // never lands on either `<g>` as a DOM attribute — so a wrapping
        // group is the only way a story can find ONE wire's rendered trace
        // among its siblings. Purely additive: `Trace` itself is untouched.
        <g key={wire.id} data-wire-id={wire.id}>
          <Trace
            id={wire.id}
            from={from}
            to={to}
            routing={wire.routing}
            variant={wire.variant ?? "data"}
            color={wire.color}
            markerEnd={wire.markerEnd}
            curve={curve}
            terminals={false}
          />
        </g>
      ))}
    </svg>
  );
}

// src/components/wiring.ts — `WireLayer`'s paint vocabulary: what a wire
// LOOKS like between two rendered dots, plus how N wires sharing one
// endpoint pair fan apart so they are visibly N (`fanWires`, D-B3).
//
// This file used to be a third thing as well: the connection RECORD, with
// its own derivation (`wiredPortKeys`). That role is absorbed — the record
// is `scene.ts`'s `SceneEdge` (source/target/sourceHandle/targetHandle,
// React Flow's own vocabulary), the derivation is `scene.ts`'s
// `wiredPorts`, and the item-state mapping moved to the adapter
// (`sceneWires.ts`'s `withWiredState`). Deleted here, deliberately:
// `wireEndKey`, `wiredPortKeys`, `withWiredState` — so there is exactly
// ONE model and this module cannot quietly grow back into a second one.
//
// What remains is view-kit only, and this file still imports NOTHING from
// `src/scene/` — `Wire` is a paint instruction a host DERIVES from a scene
// (`sceneWires.ts`), never a record a host authors as its source of truth.
// `WireLayer` (a component) imports this module, and the components-never-
// import-the-scene wall holds precisely because the scene types stay out
// of here, even transitively.
//
// The permission-free stance is unchanged (Zach, 2026-09-17: "draw as many
// wires as you want... even multiple wires between the same two ports") —
// nothing here validates; everything is derivation over whatever list it
// is handed.

import type { TraceMarkerEnd, TraceRouting, TraceVariant } from "./trace.layout";

/* ------------------------------------------------------------------ */
/* The paint instruction                                               */
/* ------------------------------------------------------------------ */

export interface WireEnd {
  blockId: string;
  portId: string;
}

export interface Wire {
  id: string;
  /** The initiating end — the arrowhead points AT `to` (`Trace`'s own
   *  default `markerEnd: "arrow"`). A scene edge's source/target map to
   *  from/to with the arrow direction preserved (`sceneWires.ts`). */
  from: WireEnd;
  to: WireEnd;
  /** Default `"data"`; the async gallery passes `"async"` (D-B6's reading
   *  of the donor's "new wires default to async", `asyncRegionModel.ts`). */
  variant?: TraceVariant;
  /** Default is `Trace`'s own default (`"curved"`). */
  routing?: TraceRouting;
  /** Default is `Trace`'s own default (`"arrow"`). */
  markerEnd?: TraceMarkerEnd;
  color?: string;
}

/* ------------------------------------------------------------------ */
/* Duplicate fan (D-B3)                                                */
/* ------------------------------------------------------------------ */

/** Perpendicular spread between duplicate wires sharing one endpoint pair —
 *  otherwise "two wires between the same two ports" draws as one line drawn
 *  twice and the gallery shows nothing. */
export const DUPLICATE_FAN_PX = 14;

/** Unordered: a wire and a same-pair wire drawn the other way (`a→b` beside
 *  `b→a`) still fan against each other — the visible fact is "N wires
 *  between these two dots", not which end either one calls `from`. The same
 *  rule the scene kit's `duplicateEdges` lint applies, restated over the
 *  paint vocabulary, so the lint and the drawing can never disagree about
 *  what counts as a duplicate. */
function unorderedPairKey(a: WireEnd, b: WireEnd): string {
  const ka = `${a.blockId}/${a.portId}`;
  const kb = `${b.blockId}/${b.portId}`;
  return ka <= kb ? `${ka}|${kb}` : `${kb}|${ka}`;
}

export interface WireFan {
  /** This wire's 0-based rank among the others sharing its endpoint pair. */
  index: number;
  /** How many wires share this endpoint pair, this one included. */
  count: number;
  /** The `curve` offset `Trace` already understands (`trace.routing.ts`'s
   *  `TraceCurve`) — `{dx: 0, dy: ...}` per plan §5, centred on 0 so a lone
   *  wire between a pair fans by nothing at all. */
  offset: { dx: number; dy: number };
}

/** One `WireFan` per wire, in `wires`' own order, so `WireLayer` can zip it
 *  straight back onto the same array instead of re-grouping a second time. */
export function fanWires(wires: readonly Wire[]): WireFan[] {
  const idsByPair = new Map<string, string[]>();
  for (const wire of wires) {
    const key = unorderedPairKey(wire.from, wire.to);
    const ids = idsByPair.get(key);
    if (ids) ids.push(wire.id);
    else idsByPair.set(key, [wire.id]);
  }
  const rankById = new Map<string, { index: number; count: number }>();
  for (const ids of idsByPair.values()) {
    ids.forEach((id, index) => rankById.set(id, { index, count: ids.length }));
  }
  return wires.map((wire) => {
    const rank = rankById.get(wire.id)!;
    const dy = (rank.index - (rank.count - 1) / 2) * DUPLICATE_FAN_PX;
    return { index: rank.index, count: rank.count, offset: { dx: 0, dy } };
  });
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/*
 * CodeEditor — reconciled from packages/bbox-ui/src/codeField.css (current
 * on main: the box chrome, caret/selection/placeholder colours) and
 * claude/code-block-primitive's codeBlock.css (recovered: the opaque
 * gutter, the overflow/scroll variants, the tok-* syntax palette — all
 * deleted from main's codeField.css by 368a524's trim). Colours are stock
 * shadcn tokens (src/globals.css) — this app carries no bbox-* theme
 * tokens, so the `var(--bbox-accent, #4f6ee5)` shape below always falls
 * through to its literal, same pattern as editableText.tsx's
 * `var(--bbox-ring, currentColor)`.
 */

.bbox-code-editor {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  padding: 4px 6px;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  /* `--bbox-tok-bg`/`--bbox-tok-fg` (codeEditorTheme.ts): a syntax theme is
     a background + foreground pair, not just token colours — a Dark Modern
     editor on the page's own light card is not Dark Modern. Unset, both
     fall through to today's literals unchanged. */
  background: var(--bbox-tok-bg, var(--color-card));
  color: var(--bbox-tok-fg, var(--color-foreground));
  cursor: text;
  overflow: hidden;
}

.bbox-code-editor[aria-disabled="true"] {
  opacity: 0.6;
  cursor: default;
}

.bbox-code-editor:focus-within {
  border-color: var(--color-primary);
}

.bbox-code-editor .cm-editor {
  outline: none;
  background: transparent;
  height: auto;
}

.bbox-code-editor .cm-scroller {
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  /* Inherits the box's own inline `fontSize` (`fontSizePx`) rather than
     hardcoding a copy — the only way a per-instance size reaches
     CodeMirror's internal DOM. */
  font-size: inherit;
  line-height: 1.4;
}

/*
 * `overflow` (codeEditor.tsx): what a line wider than the box does.
 * `clip` — an <input>-like port label: cut at the edge, no bar. `scroll` —
 * a real horizontal scrollbar once content is wider than the box (the IDE
 * feel of Zach's screenshot). `wrap` — CodeMirror's own `lineWrapping`
 * folds the line, so the scroller only ever needs to grow vertically.
 */
.bbox-code-editor[data-overflow="clip"] .cm-scroller {
  overflow: hidden;
}

.bbox-code-editor[data-overflow="scroll"] .cm-scroller,
.bbox-code-editor[data-overflow="wrap"] .cm-scroller {
  overflow: auto;
}

.bbox-code-editor .cm-content {
  padding: 0;
  caret-color: var(--color-primary);
}

/*
 * No `white-space` set on `.cm-content` above, on purpose — measured live (headless Chrome):
 * CodeMirror's OWN base theme already puts `white-space: pre` on
 * `.cm-content` at the SAME specificity as a plain `.bbox-code-editor
 * .cm-content` rule would be (two classes each), and CodeMirror's
 * stylesheet is injected at `EditorView` construction time, i.e. AFTER this
 * file's import — so it wins the cascade tie regardless of what this rule
 * declared. codeBlock.css's own `white-space: nowrap` here had the exact
 * same dead-on-arrival shape (confirmed: the recovered branch never beat
 * this tie either). It doesn't matter: `pre` already gives "no soft wrap"
 * (CodeMirror still renders one `.cm-line` per line regardless of this
 * property), and unlike `nowrap` it does NOT collapse a run of leading
 * spaces — which Python's indentation needs. Fighting the cascade for
 * `nowrap` here would have made indentation render wrong the moment it won.
 */

/* WHY this rule exists at all: CodeMirror's `lineWrapping` sets
   `white-space: pre-wrap` through its own `.ͼ1 .cm-lineWrapping` rule —
   specificity (0,2,0), the SAME as `.cm-content` alone, so which wins would
   otherwise depend on stylesheet order. Three classes settles it. */
.bbox-code-editor .cm-content.cm-lineWrapping {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.bbox-code-editor .cm-line {
  padding: 0;
}

/* The line-number gutter (`lineNumbers`): a hairline on its right, numbers
   in the faint ink, room for a few digits before the content's own padding.
   WHY it needs a REAL (opaque) background, not `transparent`: CodeMirror
   pins the gutter with its own `position: sticky; left: 0` so it stays put
   while `.cm-content`'s lines scroll underneath it horizontally
   (`data-overflow="scroll"`/`"wrap"` above). A transparent gutter lets that
   scrolled text show through behind the numbers as it passes — matching the
   editor's own surface colour, not the page's, keeps it opaque without
   drawing a visibly different panel. This is the fix codeBlock.css shipped
   and main's codeField.css trim lost along with the gutter entirely. */
.bbox-code-editor .cm-gutters {
  background: var(--color-card);
  color: var(--color-muted-foreground);
  border-right: 1px solid var(--color-border);
  min-width: 36px;
  justify-content: flex-end;
  margin-right: 12px;
}

.bbox-code-editor .cm-lineNumbers .cm-gutterElement {
  padding: 0 8px 0 6px;
}

.bbox-code-editor .cm-focused .cm-activeLine,
.bbox-code-editor .cm-focused .cm-activeLineGutter {
  background: color-mix(in srgb, var(--color-primary) 7%, transparent);
}

.bbox-code-editor .cm-placeholder {
  color: var(--color-muted-foreground);
  font-style: normal;
}

.bbox-code-editor .cm-selectionBackground,
.bbox-code-editor .cm-focused .cm-selectionBackground,
.bbox-code-editor ::selection {
  background: color-mix(in srgb, var(--color-primary) 30%, transparent);
}

.bbox-code-editor .cm-cursor {
  border-left-color: var(--color-primary);
}

/*
 * The syntax palette. `classHighlighter` (@lezer/highlight) emits stable
 * `tok-*` classes with no colour of its own; this is the one place they get
 * one, ported from codeBlock.css's `bbox-code-tokens` block.
 *
 * WHY every selector carries BOTH root classes (0,3,0): CodeMirror's own
 * fallback highlight style, when a host happens to mount it, paints tokens
 * through generated `.ͼN .ͼM` rules at (0,2,0) — a bare
 * `.bbox-code-tokens .tok-keyword` would tie on specificity and lose or win
 * by stylesheet order. Three classes settles it in this sheet's favour.
 *
 * WHY each rule now reads `var(--bbox-tok-*, <today's literal>)`
 * (docs/FEEDBACK-2026-09-17b-PLAN.md A-2, codeEditorTheme.ts): a VS Code
 * syntax theme is a PALETTE SWAP over this exact selector set, not a
 * second highlighter or a per-theme CodeMirror `EditorView.theme()` — see
 * codeEditor.tsx:297's own WHY. `codeEditorThemeVars()` sets the
 * `--bbox-tok-*` custom properties inline on the root; with none set (the
 * default, and any unrecognised theme id) every rule falls straight
 * through to the literal it had before this change, byte-identical.
 */
.bbox-code-editor.bbox-code-tokens .tok-keyword,
.bbox-code-editor.bbox-code-tokens .tok-operatorKeyword,
.bbox-code-editor.bbox-code-tokens .tok-definitionKeyword,
.bbox-code-editor.bbox-code-tokens .tok-moduleKeyword {
  color: var(--bbox-tok-keyword, color-mix(in srgb, var(--bbox-accent, #4f6ee5) 78%, var(--color-foreground)));
  font-weight: 600;
}

/* Split from the group above so a theme's "control keyword" row
   (if/for/return/…) has somewhere to land — see codeEditorTheme.ts's own
   WHY on why `classHighlighter` never actually emits this class today. */
.bbox-code-editor.bbox-code-tokens .tok-controlKeyword {
  color: var(--bbox-tok-control-keyword, color-mix(in srgb, var(--bbox-accent, #4f6ee5) 78%, var(--color-foreground)));
  font-weight: 600;
}

.bbox-code-editor.bbox-code-tokens .tok-string,
.bbox-code-editor.bbox-code-tokens .tok-docString,
.bbox-code-editor.bbox-code-tokens .tok-character,
.bbox-code-editor.bbox-code-tokens .tok-attributeValue {
  color: var(--bbox-tok-string, color-mix(in srgb, var(--bbox-success, #2f9e5a) 62%, var(--color-foreground)));
}

.bbox-code-editor.bbox-code-tokens .tok-number,
.bbox-code-editor.bbox-code-tokens .tok-integer,
.bbox-code-editor.bbox-code-tokens .tok-float,
.bbox-code-editor.bbox-code-tokens .tok-bool,
.bbox-code-editor.bbox-code-tokens .tok-atom,
.bbox-code-editor.bbox-code-tokens .tok-null,
.bbox-code-editor.bbox-code-tokens .tok-unit {
  color: var(--bbox-tok-number, color-mix(in srgb, var(--bbox-warning, #c98a1b) 58%, var(--color-foreground)));
}

.bbox-code-editor.bbox-code-tokens .tok-comment,
.bbox-code-editor.bbox-code-tokens .tok-lineComment,
.bbox-code-editor.bbox-code-tokens .tok-blockComment,
.bbox-code-editor.bbox-code-tokens .tok-meta {
  color: var(--bbox-tok-comment, var(--color-muted-foreground));
  font-style: italic;
}

.bbox-code-editor.bbox-code-tokens .tok-typeName,
.bbox-code-editor.bbox-code-tokens .tok-className,
.bbox-code-editor.bbox-code-tokens .tok-namespace {
  color: var(--bbox-tok-type, color-mix(in srgb, var(--bbox-accent, #4f6ee5) 55%, var(--color-foreground)));
}

.bbox-code-editor.bbox-code-tokens .tok-variableName,
.bbox-code-editor.bbox-code-tokens .tok-variableName2,
.bbox-code-editor.bbox-code-tokens .tok-definition,
.bbox-code-editor.bbox-code-tokens .tok-self {
  color: var(--bbox-tok-variable, var(--bbox-accent, #4f6ee5));
}

.bbox-code-editor.bbox-code-tokens .tok-propertyName,
.bbox-code-editor.bbox-code-tokens .tok-attributeName,
.bbox-code-editor.bbox-code-tokens .tok-labelName {
  color: color-mix(in srgb, var(--bbox-danger, #c94b3f) 42%, var(--color-foreground));
}

/* WHY the fallback reads `var(--bbox-accent, #4f6ee5))` (the tok-variableName
   rule's own default above) and not `var(--color-foreground)`: this
   selector was dead until codeEditorHighlight.ts (its own WHY) started
   actually emitting `tok-function` — nothing ever exercised this rule's
   own literal, so it was never noticed that it disagreed with what a
   function name actually rendered as (`.tok-variableName`'s colour, since
   `.tok-function`/`.tok-definition`/`.tok-variableName` are now emitted
   together on the SAME element — see that file's own WHY on unioning
   classes). Every theme sets `--bbox-tok-function` explicitly, so this
   fallback only matters with no theme selected, and it has to match
   tok-variableName's fallback exactly or turning the class "on" silently
   recolours every function name (and call site) the moment no theme is
   set — a real regression, not a fidelity gain. */
.bbox-code-editor.bbox-code-tokens .tok-function,
.bbox-code-editor.bbox-code-tokens .tok-macroName {
  color: var(--bbox-tok-function, var(--bbox-accent, #4f6ee5));
  font-weight: 600;
}

.bbox-code-editor.bbox-code-tokens .tok-operator,
.bbox-code-editor.bbox-code-tokens .tok-punctuation,
.bbox-code-editor.bbox-code-tokens .tok-separator,
.bbox-code-editor.bbox-code-tokens .tok-bracket {
  color: var(--bbox-tok-operator, var(--color-muted-foreground));
}

.bbox-code-editor.bbox-code-tokens .tok-invalid {
  color: var(--bbox-danger, #c94b3f);
}
